#ifndef COMMON_H
#define COMMON_H

#include "types.h"
#if defined(TARGET_PC)
/* the PC port includes no MIPS assembly: the rodata is in the executable it
 * loads, at its addresses */
#define INCLUDE_ASM(FOLDER, NAME)
#define INCLUDE_RODATA(FOLDER, NAME)
#elif !defined(M2CTX)
#include "include_asm.h" /* generated by splat (make extract) */
#endif

/* file-local variables of the game. The PC port uses them at their
 * PlayStation addresses, which position-independent code (Android) can only
 * reach for global symbols. */
#ifdef TARGET_PC
#define STATIC_DATA
#else
#define STATIC_DATA static
#endif

#endif /* COMMON_H */
